        acc0.y += v0.y * w0 + v1.y * w1 + v2.y * w2;
        acc0.z += v0.z * w0 + v1.z * w1 + v2.z * w2;
        acc0.w += v0.w * w0 + v1.w * w1 + v2.w * w2;
        acc1.x += v1.x * w0 + v2.x * w1 + v3.x * w2;
        acc1.y += v1.y * w0 + v2.y * w1 + v3.y * w2;
        acc1.z += v1.z * w0 + v2.z * w1 + v3.z * w2;
        acc1.w += v1.w * w0 + v2.w * w1 + v3.w * w2;
        acc2.x += v2.x * w0 + v3.x * w1 + v4.x * w2;
        acc2.y += v2.y * w0 + v3.y * w1 + v4.y * w2;
        acc2.z += v2.z * w0 + v3.z * w1 + v4.z * w2;
        acc2.w += v2.w * w0 + v3.w * w1 + v4.w * w2;
        acc3.x += v3.x * w0 + v4.x * w1 + v5.x * w2;
        acc3.y += v3.y * w0 + v4.y * w1 + v5.y * w2;
        acc3.z += v3.z * w0 + v4.z * w1 + v5.z * w2;
        acc3.w += v3.w * w0 + v4.w * w1 + v5.w * w2;
