            if (xo + 3 < OW) {
                *reinterpret_cast<float4*>(&out[oi]) = acc1;
            } else {
                out[oi] = acc1.x;
                if (xo + 1 < OW) out[oi + 1] = acc1.y;
                if (xo + 2 < OW) out[oi + 2] = acc1.z;
