    const int64_t SW = (TILE_X - 1) * stride + 1;
    const int64_t SH = (OUT_TILE_Y - 1) * stride + (K - 1) * dilation + 1;
    const int64_t smem_bytes64 = SH * SW * c10::elementSize(xc.scalar_type());
    TORCH_CHECK(smem_bytes64 <= 48 * 1024);
